CREATE TABLE "Product" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "category" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "salePrice" INTEGER NOT NULL, "supplierCost" INTEGER NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Order" ("id" TEXT NOT NULL PRIMARY KEY, "publicId" TEXT NOT NULL, "productId" TEXT NOT NULL, "productNameSnapshot" TEXT NOT NULL, "instagramUsername" TEXT NOT NULL, "customerName" TEXT, "customerEmail" TEXT NOT NULL, "amount" INTEGER NOT NULL, "supplierCostSnapshot" INTEGER NOT NULL, "grossProfitSnapshot" INTEGER NOT NULL, "paymentStatus" TEXT NOT NULL DEFAULT 'pending', "fulfillmentStatus" TEXT NOT NULL DEFAULT 'waiting_payment', "mercadoPagoPaymentId" TEXT, "mercadoPagoReference" TEXT, "telegramNotifiedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Order_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Order_publicId_key" ON "Order"("publicId"); CREATE UNIQUE INDEX "Order_mercadoPagoPaymentId_key" ON "Order"("mercadoPagoPaymentId"); CREATE UNIQUE INDEX "Order_mercadoPagoReference_key" ON "Order"("mercadoPagoReference");
CREATE TABLE "PaymentEvent" ("id" TEXT NOT NULL PRIMARY KEY, "externalId" TEXT NOT NULL, "topic" TEXT NOT NULL, "payload" TEXT NOT NULL, "orderId" TEXT, "processedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PaymentEvent_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order" ("id") ON DELETE SET NULL ON UPDATE CASCADE); CREATE UNIQUE INDEX "PaymentEvent_externalId_key" ON "PaymentEvent"("externalId");
CREATE TABLE "AppSetting" ("key" TEXT NOT NULL PRIMARY KEY, "value" TEXT NOT NULL, "updatedAt" DATETIME NOT NULL);
ALTER TABLE "Order" ADD COLUMN "telegramNotificationProcessingAt" DATETIME;
ALTER TABLE "Order" ADD COLUMN "telegramNotificationError" TEXT;
CREATE INDEX "Order_createdAt_idx" ON "Order"("createdAt");
CREATE INDEX "Order_paymentStatus_fulfillmentStatus_idx" ON "Order"("paymentStatus", "fulfillmentStatus");
CREATE INDEX "PaymentEvent_orderId_idx" ON "PaymentEvent"("orderId");
